package com.juner2026.crabpet;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.util.Base64;import android.view.*;import android.widget.*;

public class PetService extends Service {
 private WindowManager wm;private FrameLayout root;private WindowManager.LayoutParams lp;private ImageView crabView;private TextView bubble;private final Handler h=new Handler(Looper.getMainLooper());
 private CompanionMonitor monitor;private float downX,downY,startRawX,startRawY;private long downTime;private boolean moved;private int tapCount,effectIx;
 private static final String[] B64={
"",
"",
"",
"",
"",
""};
 private static final String[] LINES={"啾","想你了","抱抱","再戳一下","你回来啦","不许走","喜欢你","贴贴"};
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int f,int id){channel();startForeground(7,notification());show();monitor=new CompanionMonitor(this,(line,heat)->say(line));monitor.start();return START_STICKY;}
 private void channel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("pet","AI小螃蟹",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);}}
 private Notification notification(){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"pet"):new Notification.Builder(this);return b.setContentTitle("AI小螃蟹").setContentText("Clawd 桌宠").setSmallIcon(android.R.drawable.ic_dialog_info).setOngoing(true).build();}

 private void show(){if(root!=null)return;wm=(WindowManager)getSystemService(WINDOW_SERVICE);root=new FrameLayout(this);
  byte[] raw=Base64.decode(B64[0],Base64.DEFAULT);Bitmap bt=BitmapFactory.decodeByteArray(raw,0,raw.length);crabView=new ImageView(this);crabView.setImageBitmap(bt);root.addView(crabView,new FrameLayout.LayoutParams(230,230));
  bubble=new TextView(this);bubble.setText("啾");bubble.setTextColor(Color.rgb(80,48,62));bubble.setTextSize(11);bubble.setGravity(Gravity.CENTER);bubble.setPadding(12,5,12,5);GradientDrawable g=new GradientDrawable();g.setColor(Color.rgb(255,240,248));g.setStroke(2,Color.rgb(244,176,204));g.setCornerRadius(18);bubble.setBackground(g);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(-2,36);bp.leftMargin=86;bp.topMargin=12;root.addView(bubble,bp);
  lp=new WindowManager.LayoutParams(240,250,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.START;lp.x=30;lp.y=260;wm.addView(root,lp);
  h.post(loop);attachTouch();}
 Runnable loop=new Runnable(){public void run(){float b=Math.round(Math.sin(System.currentTimeMillis()/300.0)*6);crabView.setTranslationY(b);h.postDelayed(this,160);}};

 private int poseIx=0;
 private void attachTouch(){root.setOnTouchListener((v,e)->{
  switch(e.getAction()){
   case MotionEvent.ACTION_DOWN:downTime=System.currentTimeMillis();downX=e.getRawX();downY=e.getRawY();startRawX=e.getRawX();startRawY=e.getRawY();moved=false;return true;
   case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-downX,dy=e.getRawY()-downY;if(Math.abs(dx)>8||Math.abs(dy)>8)moved=true;lp.x=(int)(startRawX-(v.getWidth()/2));lp.y=(int)(startRawY-(v.getHeight()/2));downX=e.getRawX();downY=e.getRawY();wm.updateViewLayout(root,lp);return true;
   case MotionEvent.ACTION_UP:long dur=System.currentTimeMillis()-downTime;if(!moved){if(dur>650){say("藏一下");root.setVisibility(View.INVISIBLE);h.postDelayed(()->root.setVisibility(View.VISIBLE),2200);}else{tapCount++;poseIx=(poseIx+1)%B64.length;byte[] r=Base64.decode(B64[poseIx],Base64.DEFAULT);crabView.setImageBitmap(BitmapFactory.decodeByteArray(r,0,r.length));effect();say(LINES[tapCount%LINES.length]);if(monitor!=null)monitor.touched();h.postDelayed(()->tapCount=0,900);}}return true;
  }return true;});}
 private void say(String s){bubble.setText(s);bubble.setVisibility(View.VISIBLE);h.removeCallbacks(hide);h.postDelayed(hide,3600);}Runnable hide=new Runnable(){public void run(){bubble.setVisibility(View.GONE);}};
 private void effect(){effectIx++;TextView e=new TextView(this);String[] pool={"✦","♥","♪","♫","☁","!"};e.setText(pool[effectIx%pool.length]);e.setTextSize(22);e.setTextColor(new int[]{Color.rgb(255,190,50),Color.rgb(255,110,155),Color.rgb(190,150,255),Color.rgb(255,110,155),Color.rgb(100,205,255),Color.rgb(225,70,70)}[effectIx%6]);root.addView(e,new FrameLayout.LayoutParams(-2,-2));e.setX((float)(90+Math.random()*50));e.setY(60);e.animate().translationY(-40).alpha(0).setDuration(1500).withEndAction(()->root.removeView(e)).start();}
 public void onDestroy(){if(monitor!=null)monitor.stop();if(root!=null&&wm!=null)wm.removeView(root);super.onDestroy();}
}
